def maxPatternSubsequences(s, pattern):
    x, y = pattern[0], pattern[1]
    if x == y:
        c = s.count(x)
        return c * (c + 1) // 2
    cx = cy = pairs = 0
    for ch in s:
        if ch == y:
            pairs += cx
            cy += 1
        if ch == x:
            cx += 1
    return pairs + max(cx, cy)
